package io.github.hectorespert.jmediasoup.rtp;

import io.github.hectorespert.jmediasoup.internal.Checks;
import java.util.List;
import org.jspecify.annotations.Nullable;

/**
 * The RTP parameters of a media stream: those a producer sends to mediasoup, or those mediasoup
 * sends to a consumer.
 *
 * <p>The parameters of a producer can have several encodings (simulcast), each with an
 * {@code ssrc} or a {@code rid}. Those of a consumer have a single encoding with SSRCs generated by
 * mediasoup, and no {@code mid}.
 *
 * @param mid the MID RTP extension value, as defined in the BUNDLE specification, or {@code null}
 *     if absent
 * @param codecs the media and RTX codecs in use
 * @param headerExtensions the RTP header extensions in use
 * @param encodings the RTP streams sent and their settings
 * @param rtcp the RTCP settings, or {@code null} if absent
 * @param msid the media stream and track identifiers, or {@code null} if absent
 */
public record RtpParameters(
        @Nullable String mid,
        List<RtpCodecParameters> codecs,
        List<RtpHeaderExtensionParameters> headerExtensions,
        List<RtpEncodingParameters> encodings,
        @Nullable RtcpParameters rtcp,
        @Nullable String msid) {

    /** Copies the lists, with absent ones as empty. */
    public RtpParameters {
        codecs = Checks.list(codecs, "codecs");
        headerExtensions = Checks.list(headerExtensions, "headerExtensions");
        encodings = Checks.list(encodings, "encodings");
    }
}
